'use client'

import { useState, type ComponentProps } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import type { AccentColor } from '@/theme/palettes'
import { Tooltip, TooltipGroup } from '../overlays/Tooltip'
import { Badge, type BadgeProps } from './Badge'
import styles from './Avatar.module.css'

type AvatarStatus = 'online' | 'away' | 'busy' | 'offline'

// Badge's presence colours, so a dot on an avatar and a dot beside a name match.
const STATUS: Record<AvatarStatus, { variant: BadgeProps['variant']; label: string }> = {
  online: { variant: 'success', label: 'Online' },
  away: { variant: 'warning', label: 'Away' },
  busy: { variant: 'destructive', label: 'Busy' },
  offline: { variant: 'secondary', label: 'Offline' },
}

export interface AvatarProps extends ComponentProps<'span'> {
  /** 16, 24, 32, 40, 96 or 128px across: Atlassian's avatar sizes. */
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl'
  imageSrc?: string
  /** Who this is. Without it the avatar is decorative and hidden from assistive tech. */
  imageAlt?: string
  /** Shown when there is no image, or it fails to load. One or two letters; `xs` has room for the first only. */
  initials?: string
  /** Any accent hue. Unset is the neutral gray. */
  color?: AccentColor
  /** `subtle` is a tint of the hue; `solid` is its 600 step (400 in dark). */
  variant?: 'subtle' | 'solid'
  /** A presence dot at the bottom-end corner. Joins the name as ", Online" when there is `imageAlt`. */
  status?: AvatarStatus
  /** The status word in the name, for another language. Defaults to Online, Away, Busy or Offline. */
  statusLabel?: string
}

export function Avatar({
  size = 'md',
  imageSrc,
  imageAlt,
  initials,
  color,
  variant = 'subtle',
  status,
  statusLabel = status && STATUS[status].label,
  className,
  ...props
}: AvatarProps) {
  // Keyed by src, so a new imageSrc gets a fresh attempt instead of staying
  // on the fallback from the last one that failed.
  const [failedSrc, setFailedSrc] = useState<string>()
  // An empty string is no image, not a request for the page's own URL.
  const showImage = !!imageSrc && failedSrc !== imageSrc
  // 16px holds one letter at the smallest type size. A count ("+3", "9+")
  // stays whole: half of it would be a different number.
  const letters = size === 'xs' && initials && !initials.includes('+') ? Array.from(initials)[0] : initials

  return (
    <span
      // The label lives on the container so the image, the initials and the silhouette
      // all announce the same thing: the person, not "S R" or nothing.
      role={imageAlt ? 'img' : undefined}
      // Children of role="img" are not read, so the status joins the name.
      aria-label={imageAlt && status ? `${imageAlt}, ${statusLabel}` : imageAlt}
      aria-hidden={imageAlt ? undefined : true}
      // The Theme's own palette switch: on the avatar it remaps --color-background-brand-bold and
      // its tints to this hue, already measured for contrast.
      data-accent={color}
      // A CSS class cannot start with a digit.
      className={cn(styles.avatar, styles[size === '2xl' ? 'xxl' : size], styles[variant], status && styles.hasStatus, className)}
      {...props}
    >
      {showImage ? (
        <img
          src={imageSrc}
          alt=""
          className={styles.image}
          onError={() => setFailedSrc(imageSrc)}
        />
      ) : letters ? (
        <span className={styles.initials}>{letters}</span>
      ) : (
        <Icon name="user" className={styles.silhouette} />
      )}
      {status && (
        <Badge
          isDot
          variant={STATUS[status].variant}
          // 8px from sm to lg, as Figma; xl and 2xl size it in CSS, xs hides it.
          size="md"
          className={styles.status}
        />
      )}
    </span>
  )
}

export interface AvatarGroupProps extends ComponentProps<'span'> {
  /** The people, in order. Each takes Avatar's props; the group's `size` wins. */
  avatars: AvatarProps[]
  /** The most circles in the row, the "+n" included. Unset shows everyone. */
  max?: number
  size?: AvatarProps['size']
  /** The name of the "+n" avatar, for another language. Used only when the avatars are named. */
  moreLabel?: (count: number) => string
  /** Each named avatar shows its name on hover, and the "+n" lists the people it stands for, on hover or focus. */
  hasTooltips?: boolean
}

/** Avatars overlapping in a row, with a "+n" for the ones past `max`. */
export function AvatarGroup({
  avatars,
  max,
  size = 'md',
  moreLabel = (count) => `${count} more`,
  hasTooltips = false,
  className,
  ...props
}: AvatarGroupProps) {
  // The "+n" takes the last slot, so it always stands for two or more: never "+1"
  // where the person would have fitted.
  const shown = max !== undefined && avatars.length > max ? avatars.slice(0, Math.max(max - 1, 0)) : avatars
  const hidden = avatars.length - shown.length
  // Named avatars get a named "+n"; decorative ones (the names are printed) a decorative one.
  const isNamed = avatars.some((a) => a.imageAlt)

  // With tooltips, the "+n" lists who it stands for, and takes focus so
  // that list can be read by keyboard too.
  const hiddenNames = hasTooltips
    ? avatars
        .slice(shown.length)
        .map((a) => a.imageAlt)
        .filter(Boolean)
        .join(', ')
    : ''
  const more = hidden > 0 && (
    // A 16px circle holds two characters, so past nine the xs count reads "9+".
    // ponytail: larger sizes are not capped; an sm circle outgrows +99.
    <Avatar
      size={size}
      initials={size === 'xs' && hidden > 9 ? '9+' : `+${hidden}`}
      imageAlt={isNamed ? moreLabel(hidden) : undefined}
      tabIndex={hiddenNames ? 0 : undefined}
    />
  )

  const group = (
    <span className={cn(styles.group, className)} {...props}>
      {shown.map((avatar, i) => {
        const el = <Avatar {...avatar} size={size} style={{ zIndex: shown.length - i, ...avatar.style }} />
        return hasTooltips && avatar.imageAlt ? (
          <Tooltip key={i} content={avatar.imageAlt}>
            {el}
          </Tooltip>
        ) : (
          <Avatar key={i} {...avatar} size={size} style={{ zIndex: shown.length - i, ...avatar.style }} />
        )
      })}
      {more && hiddenNames ? <Tooltip content={hiddenNames}>{more}</Tooltip> : more}
    </span>
  )
  // One shared delay: once a name shows, the next shows as the pointer moves on.
  return hasTooltips ? <TooltipGroup>{group}</TooltipGroup> : group
}

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  /* Positions the status dot. */
  position: relative;
  /* Always round, whatever the Theme's radius preset: a circle is the shape,
     not a corner setting. */
  border-radius: var(--radius-pill);
  font-family: var(--font-sans);
  font-weight: 500;
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- initials sit in a fixed circle, not on the type scale */
  line-height: 1;
  user-select: none;
  vertical-align: middle;
}

.xs {
  --avatar-size: var(--avatar-xs);

  inline-size: var(--avatar-size);
  block-size: var(--avatar-size);
  /* One letter: the component drops the second at this size. */
  font-size: var(--text-body-sm);
}

.sm {
  --avatar-size: var(--avatar-sm);

  inline-size: var(--avatar-size);
  block-size: var(--avatar-size);
  font-size: var(--text-body-sm);
}

.md {
  --avatar-size: var(--avatar-md);

  inline-size: var(--avatar-size);
  block-size: var(--avatar-size);
  font-size: var(--text-body-sm);
}

.lg {
  --avatar-size: var(--avatar-lg);

  inline-size: var(--avatar-size);
  block-size: var(--avatar-size);
  font-size: var(--text-body);
}

/* The profile sizes. The type scale tops out at 32px, so the initials are a
   smaller share of the circle here than on the row sizes. */
.xl {
  --avatar-size: var(--avatar-xl);
  --avatar-status-size: var(--box-2xs);

  inline-size: var(--avatar-size);
  block-size: var(--avatar-size);
  font-size: var(--text-heading-xl);
  /* Figma's Heading/xl and Heading/2xl: semibold at the profile sizes. */
  font-weight: 600;
}

.xxl {
  --avatar-size: var(--avatar-2xl);
  --avatar-status-size: var(--box-xs);

  inline-size: var(--avatar-size);
  block-size: var(--avatar-size);
  font-size: var(--text-heading-2xl);
  font-weight: 600;
}

.image {
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
  clip-path: circle(50%);
}

.initials {
  text-transform: uppercase;
}

/* Neutral is the default: no [data-accent], so the gray surface tokens. */
.subtle {
  background: var(--color-background-neutral);
  color: var(--color-text);
}

/* --color-background-neutral-bold is gray 600 in both appearances; the token build measures
   its label on every gray ramp. */
.solid {
  background: var(--color-background-neutral-bold);
  color: var(--color-text-inverse);
}

/* With a hue, the tint and its label are measured per accent by the token
   build; solid is the accent's own fill (600 in light) and label. */
[data-accent].subtle {
  background: var(--color-background-brand-subtlest);
  color: var(--color-text-brand-bold);
}

[data-accent].solid {
  background: var(--color-background-brand-bold);
  color: var(--color-text-brand-inverse);
}

/* The kit's user icon, centred at 60% of the circle, as in Figma. It takes
   the initials' colour, measured on its fill: on solid that is
   --color-text-inverse (neutral) or --color-text-brand-inverse (a hue).
   Neutral subtle is the exception: gray 900 is too heavy for a shape this
   large, and --color-text-subtlest is measured on the same fill. */
.silhouette {
  inline-size: 60%;
  block-size: 60%;
}

.subtle:not([data-accent]) .silhouette {
  color: var(--color-text-subtlest);
}

/* On the bounding box's corner, outside the curve, as in most chat apps: the
   ring in the page colour cuts it out of the circle and any picture, as on
   a floating Badge. With a dot the circle stops clipping, so the image
   clips itself (above); the silhouette sits inside the circle anyway. */
.hasStatus {
  overflow: visible;
}

.status {
  position: absolute;
  inset-block-end: 0;
  inset-inline-end: 0;
  box-shadow: 0 0 0 2px var(--color-surface);
}

/* At 96px and up the box's corner is far off the curve, and a Badge dot is
   a speck: the dot grows and its centre sits on the circle at 45 degrees,
   which is (1 - 1/sqrt(2)) / 2 = 0.1464 of the size in from each edge. */
/* No status at 16px, as in Atlassian: the dot and its ring would cover most
   of the picture. The status stays in the accessible name. */
.xs > .status {
  display: none;
}

.xl > .status,
.xxl > .status {
  inset-block-end: calc(var(--avatar-size) * 0.1464 - var(--avatar-status-size) / 2);
  inset-inline-end: calc(var(--avatar-size) * 0.1464 - var(--avatar-status-size) / 2);
  inline-size: var(--avatar-status-size);
  block-size: var(--avatar-status-size);
}

.group {
  display: inline-flex;
  isolation: isolate;
  align-items: center;
  vertical-align: middle;
}

/* Each one tucks under the one before by 4px, Atlassian's stack, at every
   size but sm (24px), where the circles only touch, as Atlassian's small
   stack does. Each is ringed in the page colour so the circles stay apart
   whatever their colour. Earlier ones sit on top
   (z-index set inline), so a status dot on the bottom-end corner is never
   covered by the next avatar. */
.group > .avatar {
  box-shadow: 0 0 0 2px var(--color-surface);
}

.group > .avatar + .avatar {
  margin-inline-start: calc(var(--space-1) * -1);
}

.group > .sm + .sm {
  margin-inline-start: 0;
}

/* Only a group's "+n" with tooltips takes focus. */
.avatar:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset);
}
